202	    /**
203	     * The id of the existing owner this one is a soft duplicate of: an owner sharing this one's last
204	     * name and postcode but reachable on a different telephone, recorded at creation. {@code null}
205	     * when no such owner existed.
206	     */
207	    public Integer getPossibleDuplicateOf() {
208	        return this.possibleDuplicateOf;
209	    }
210	
211	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
212	        this.possibleDuplicateOf = possibleDuplicateOf;
213	    }
214	
215	    /**
216	     * Whether this owner was flagged as a possible duplicate of an existing one at creation, i.e.
217	     * whether {@link #getPossibleDuplicateOf()} identifies a matching owner.
218	     */
219	    @Transient
220	    public boolean getPossibleDuplicate() {
221	        return this.possibleDuplicateOf != null;
222	    }
223	
224	    /**
225	     * The owner's locality: the REGION portion of its {@code customerCode} (see
226	     * {@link CustomerCode}), which is the region derived from the postcode or city at creation. This
227	     * disambiguates cities that share a name. Yields {@code "UNKNOWN"} when the owner has no customer
228	     * code or it resolves to no region.
229	     */
230	    @Transient
231	    public String getLocality() {
232	        return CustomerCode.regionOf(this.customerCode);
233	    }
234	
235	    /**
236	     * The owner's IANA timezone, derived from its {@link #getLocality() locality} via the fixed
237	     * region-to-timezone table (see {@link RegionTimezone}). {@code null} when the locality has no
238	     * known timezone.
239	     */
240	    @Transient
241	    public String getTimezone() {
242	        return RegionTimezone.of(this.getLocality());
243	    }
244	
245	    /**
246	     * The owner's check digit: the single Luhn check digit computed over the digits of the
247	     * {@code customerCode}, guarding against transcription errors of the code.
248	     */
249	    @Transient
250	    public int getCheckDigit() {
251	        return Luhn.checkDigit(this.customerCode);
252	    }
253	
254	    /**
255	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
256	     * present, otherwise {@code "PHONE"}.
257	     */
258	    @Transient
259	    public String getContactPreference() {
260	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
261	    }
262	
263	    /**
264	     * The owner's telephone formatted for humans: the stored E.164 number rendered as its country
265	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). The
266	     * raw {@link #getTelephone() telephone} stays in compact E.164. See {@link E164}.
267	     */
268	    @Transient
269	    public String getTelephoneDisplay() {
270	        return E164.display(this.telephone);
271	    }
272	
273	    /**
274	     * The owner's age band: {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"} derived from the
275	     * birth date against the registration date (see {@link AgeBand}), or {@code null} when no birth
276	     * date was supplied.
277	     */
278	    @Transient
279	    public String getAgeBand() {
280	        return AgeBand.classify(this.birthDate, this.registrationDate);
281	    }
282	
283	    /**
284	     * The owner's identity key: the single derived value all duplicate detection is expressed
285	     * through, formed as {@code <normalizedTelephone>|<email or empty>|<householdId or empty>}.
286	     * Two owners are duplicates only when their whole identity keys are equal, so members of one
287	     * household (same {@code householdId}) with different telephones have different keys.
288	     */
289	    @Transient
290	    public String getIdentityKey() {
291	        return blankToEmpty(this.telephone) + '|' + blankToEmpty(this.email) + '|' + blankToEmpty(this.householdId);
292	    }
293	
294	    private static String blankToEmpty(String value) {
295	        return (value == null) ? "" : value;
296	    }
297	
298	    protected Set<Pet> getPetsInternal() {
299	        if (this.pets == null) {
300	            this.pets = new HashSet<>();
301	        }
302	        return this.pets;
303	    }
304	
305	    protected void setPetsInternal(Set<Pet> pets) {
306	        this.pets = pets;
307	    }
308	
309	    public List<Pet> getPets() {
310	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
311	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
312	        return Collections.unmodifiableList(sortedPets);
313	    }
314	
315	    public void setPets(List<Pet> pets) {
316	        this.pets = new HashSet<>(pets);
317	    }
318	
319	    public void addPet(Pet pet) {
320	        getPetsInternal().add(pet);
321	        pet.setOwner(this);
322	    }
323	
324	    /**
325	     * Return the Pet with the given name, or null if none found for this Owner.
326	     *
327	     * @param name to test
328	     * @return true if pet name is already in use
329	     */
330	    public Pet getPet(String name) {
331	        return getPet(name, false);
332	    }
333	
334	    /**
335	     * Return the Pet with the given name, or null if none found for this Owner.
336	     *
337	     * @param name to test
338	     * @return true if pet name is already in use
339	     */
340	    public Pet getPet(String name, boolean ignoreNew) {
341	        name = name.toLowerCase();
342	        for (Pet pet : getPetsInternal()) {
343	            if (!ignoreNew || !pet.isNew()) {
344	                String compName = pet.getName();
345	                compName = compName.toLowerCase();
346	                if (compName.equals(name)) {
347	                    return pet;
348	                }
349	            }
350	        }
351	        return null;
352	    }
353	
354	    public Pet getPet(Integer petId) {
355	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
356	    }
357	
358	    @Override
359	    public String toString() {
360	        return new ToStringCreator(this)
361	
362	            .append("id", this.getId())
363	            .append("new", this.isNew())
364	            .append("lastName", this.getLastName())
365	            .append("firstName", this.getFirstName())
366	            .append("address", this.address)
367	            .append("city", this.city)
368	            .append("telephone", this.telephone)
369	            .toString();
370	    }
371	}
