6	/**
7	 * Normalizes an owner request's address in place into canonical form (see {@link AddressNormalizer}):
8	 * trimmed, whitespace-collapsed, upper-cased, with common street-type abbreviations expanded. Runs
9	 * after the field is known non-blank and before the DTO is applied to an entity, so owner addresses
10	 * are stored, returned and household-checked as their normalized value.
11	 */
12	public class NormalizeOwnerAddress {
13	
14	    public void service(@Val OwnerFieldsDto request) {
15	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
16	    }
17	}
