1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Sha256;
6	import org.springframework.util.StringUtils;
7	
8	/**
9	 * Household identity shared by the create-owner steps. A household is the set of owners with the same
10	 * last name (normalized case-insensitively with collapsed whitespace) and the same postcode. Its
11	 * {@code householdId} is derived deterministically from those two values, so any two owners with the
12	 * same last name and postcode share it automatically without an explicit link. Used by
13	 * {@link AssignHouseholdId} to stamp each owner, by {@link EnsureUniqueHousehold} to reject a second
14	 * owner in an occupied household, and by {@link CountHouseholdMembers} to size the household.
15	 */
16	final class Household {
17	
18	    /** The number of leading hex characters of the SHA-256 digest that form a household id. */
19	    private static final int ID_LENGTH = 12;
20	
21	    private Household() {
22	    }
23	
24	    /** Case-insensitive form with leading/trailing and repeated inner whitespace collapsed to one space. */
25	    static String normalizeLastName(String lastName) {
26	        return lastName == null ? "" : lastName.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
27	    }
28	
29	    /**
30	     * The deterministic household id for the given last name and postcode: the first
31	     * {@value #ID_LENGTH} hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
32	     * Returns {@code null} when no postcode is supplied, since a household is keyed on postcode and an
33	     * owner without one belongs to no household.
34	     */
35	    static String idFor(String lastName, String postcode) {
36	        if (!StringUtils.hasText(postcode)) {
37	            return null;
38	        }
39	        return Sha256.hex(normalizeLastName(lastName) + '|' + postcode).substring(0, ID_LENGTH);
40	    }
41	}
