1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Stamps a newly built owner with its deterministic {@code householdId}, derived from its last name
8	 * and postcode (see {@link Household}). Because the id is a pure function of those two values, owners
9	 * that share a last name and postcode share the id automatically — no explicit opt-in creates the
10	 * link. An owner without a postcode belongs to no household and is left without an id.
11	 *
12	 * <p>Runs under the request transaction, after {@link BuildOwner}, so later steps that key off the
13	 * household ({@link EnsureUniqueHousehold}, {@link CountHouseholdMembers}, {@link EnsureUniqueIdentity}
14	 * via the identity key) see the final id.
15	 */
16	public class AssignHouseholdId {
17	
18	    public void service(@Val Owner owner) {
19	        owner.setHouseholdId(Household.idFor(owner.getLastName(), owner.getPostcode()));
20	    }
21	}
