1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.HouseholdDuplicateException;
9	
10	/**
11	 * Enforces one owner per household on create. Because the household is keyed on (last name, postcode)
12	 * via the deterministic {@link Owner#getHouseholdId() householdId}, a second owner whose id already
13	 * belongs to an existing owner is a household duplicate and is rejected with 409 — unless the request
14	 * opts in with {@code sharesHousehold=true}, which bypasses the rejection and admits the owner as a
15	 * declared household member. In that case it publishes {@link DeclaredHouseholdMember} so
16	 * {@link DetectPossibleDuplicate} leaves the declared member unflagged.
17	 *
18	 * <p>Runs after {@link AssignHouseholdId} so the owner carries its final id, and before
19	 * {@link SaveOwner} so a rejection happens before anything is persisted. An owner without a postcode
20	 * belongs to no household and is always admitted.
21	 */
22	public class EnsureUniqueHousehold {
23	
24	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository,
25	            Out<DeclaredHouseholdMember> declaredMember) throws HouseholdDuplicateException {
26	        String householdId = owner.getHouseholdId();
27	        if (householdId == null || householdId.isBlank()) {
28	            return;
29	        }
30	        boolean occupied = ownerRepository.findByLastName(owner.getLastName()).stream()
31	                .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
32	        if (!occupied) {
33	            return;
34	        }
35	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
36	            throw new HouseholdDuplicateException(householdId);
37	        }
38	        declaredMember.set(DeclaredHouseholdMember.INSTANCE);
39	    }
40	}
