1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records on the newly built owner how many members its household will have once this create
9	 * completes — the existing owners sharing its {@code householdId} plus this one. Runs after
10	 * {@link AssignHouseholdId} has stamped the deterministic id and before the owner is saved, so the
11	 * size reflects the household immediately after this create. An owner belonging to no household (no
12	 * postcode) has a size of 1.
13	 */
14	public class CountHouseholdMembers {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        if (householdId == null || householdId.isBlank()) {
19	            owner.setHouseholdSize(1);
20	            return;
21	        }
22	        long existing = ownerRepository.findByLastName(owner.getLastName()).stream()
23	            .filter(member -> householdId.equals(member.getHouseholdId()))
24	            .count();
25	        owner.setHouseholdSize((int) (existing + 1));
26	    }
27	}
