1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed region-to-postcode-range lookup used to validate an owner's postcode against the region
7	 * derived from its city (see {@link CityRegion}). A region not listed here — including
8	 * {@link CityRegion#UNKNOWN} — imposes no range constraint, so any 4-digit postcode is accepted.
9	 */
10	public final class RegionPostcodes {
11	
12	    /** Region -> inclusive 4-digit postcode range {@code {low, high}}. */
13	    private static final Map<String, int[]> REGION_TO_RANGE = Map.of(
14	        "NSW", new int[] {2000, 2099},
15	        "VIC", new int[] {3000, 3099},
16	        "QLD", new int[] {4000, 4099});
17	
18	    private RegionPostcodes() {
19	    }
20	
21	    /**
22	     * Whether {@code postcode} is permitted in {@code region}: {@code true} for any region without a
23	     * known range, otherwise only when it falls inside that region's inclusive range.
24	     */
25	    public static boolean isInRange(String region, int postcode) {
26	        int[] range = REGION_TO_RANGE.get(region);
27	        return range == null || (postcode >= range[0] && postcode <= range[1]);
28	    }
29	
30	    /**
31	     * The region whose range contains {@code postcode}, or {@code null} when {@code postcode} is
32	     * absent, not a 4-digit value, or in no known range. Used to derive locality from the postcode
33	     * ahead of the city.
34	     */
35	    public static String regionOf(String postcode) {
36	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
37	            return null;
38	        }
39	        int value = Integer.parseInt(postcode);
40	        for (Map.Entry<String, int[]> entry : REGION_TO_RANGE.entrySet()) {
41	            int[] range = entry.getValue();
42	            if (value >= range[0] && value <= range[1]) {
43	                return entry.getKey();
44	            }
45	        }
46	        return null;
47	    }
48	}
