1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.function.Predicate;
4	
5	/**
6	 * The owner customer code identity, formatted {@code <REGION>-<HASH8>}: REGION is the region code
7	 * derived from the owner's postcode (falling back to its city, else {@link CityRegion#UNKNOWN}) and
8	 * HASH8 is the first 8 upper-case hex characters of SHA-256 over the normalized telephone followed by
9	 * the last name (e.g. {@code NSW-1A2B3C4D}).
10	 *
11	 * <p>It is the single identity every downstream value is derived from: the membership number and its
12	 * check digit are built from the whole code, and the owner's {@link Owner#getLocality() locality} is
13	 * the REGION read back out of it.
14	 */
15	public final class CustomerCode {
16	
17	    /** Number of leading hex characters of the hash kept in the code. */
18	    private static final int HASH_LENGTH = 8;
19	
20	    private CustomerCode() {
21	    }
22	
23	    /**
24	     * The customer code for an owner in {@code region} whose normalized telephone and last name are
25	     * {@code telephone} and {@code lastName}.
26	     */
27	    public static String of(String region, String telephone, String lastName) {
28	        return region + "-" + Sha256.hex(telephone + lastName).substring(0, HASH_LENGTH);
29	    }
30	
31	    /**
32	     * A unique variant of {@code base}: {@code base} itself when {@code taken} reports it free,
33	     * otherwise {@code base-<n>} with the smallest {@code n >= 2} that {@code taken} reports free.
34	     * Used to de-duplicate a derived code against the codes already in use.
35	     */
36	    public static String deduplicate(String base, Predicate<String> taken) {
37	        if (!taken.test(base)) {
38	            return base;
39	        }
40	        for (int n = 2; ; n++) {
41	            String candidate = base + "-" + n;
42	            if (!taken.test(candidate)) {
43	                return candidate;
44	            }
45	        }
46	    }
47	
48	    /**
49	     * The REGION portion of {@code customerCode} — everything before the first {@code '-'} — or
50	     * {@link CityRegion#UNKNOWN} when the code is absent or carries no region.
51	     */
52	    public static String regionOf(String customerCode) {
53	        if (customerCode == null) {
54	            return CityRegion.UNKNOWN;
55	        }
56	        int dash = customerCode.indexOf('-');
57	        return dash < 0 ? CityRegion.UNKNOWN : customerCode.substring(0, dash);
58	    }
59	}
